    public static bool Has(string name) => Paths.ContainsKey(name);

    /// <summary>A small glyph for <paramref name="name"/>, or null when there is none.</summary>
    public static Control? Create(string name, IBrush fill, double size = 18)
    {
        if (!Paths.TryGetValue(name, out var data)) return null;
        return new Avalonia.Controls.Shapes.Path
        {
            Data = StreamGeometry.Parse(data),
            Fill = fill,
            Stretch = Stretch.Uniform,
            Width = size,
            Height = size,
            IsHitTestVisible = false
        };
    }
